def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 140:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_factor = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_factor < 0:
        supply_factor = 0.0
    if supply_factor > 1:
        supply_factor = 1.0

    tight_supply = supply <= 17
    abundant_supply = supply >= 22

    if hp <= 2 or no_water_days >= 2:
        base = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif hp <= 4 or no_water_days >= 1:
        base = max(DAILY_SALARY * 0.72, avg_prev + 2.0)
    else:
        if abundant_supply:
            base = DAILY_SALARY * 0.28
        elif tight_supply:
            base = DAILY_SALARY * 0.58
        else:
            base = DAILY_SALARY * 0.42

        if highest_prev > 0:
            if highest_prev >= 140:
                base = min(base, DAILY_SALARY * 0.4)
            elif highest_prev >= 95:
                base = max(base, DAILY_SALARY * 0.5)
            elif highest_prev >= 60:
                base = max(base, highest_prev + 1.5)
            else:
                base = max(base, avg_prev + 1.0)

    if desperate_count >= 2:
        base += 8.0
    elif desperate_count == 1:
        base += 4.0

    if rich_count >= 2 and tight_supply:
        base += 10.0
    elif rich_count >= 1 and tight_supply:
        base += 5.0

    if abundant_supply:
        base -= 6.0

    if day >= 8 and hp > 4 and no_water_days == 0:
        base -= 4.0

    reserve_floor = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    max_affordable = budget
    if hp > 3 and no_water_days == 0:
        max_affordable = max(0.0, budget - reserve_floor)
        if max_affordable <= 0:
            max_affordable = min(budget, DAILY_SALARY * 0.35)

    bid = min(base, max_affordable)
    if hp <= 2 or no_water_days >= 2:
        bid = min(max(base, DAILY_SALARY * 0.95), budget)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', True) and o.get('hp', 0) > 0:
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    yesterday_bids = []
    yesterday_pressures = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass
        # Use yesterday hp_after as a proxy for how costly their last bids were
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            try:
                yesterday_pressures.append((float(hp_after), float(bid) if bid is not None else None))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Pressure thresholds tuned to the observed meta-round (bids ~50-160+)
    high_pressure = highest_prev_bid >= DAILY_SALARY * 1.2  # >=108
    medium_pressure = (highest_prev_bid >= DAILY_SALARY * 0.7) and (highest_prev_bid < DAILY_SALARY * 1.2)  # 63-107

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Risk-aware base bid: if we're near critical hp or have accumulated no-water days, bid more.
    if my_hp <= 2.0 or no_water_days >= 2:
        base = DAILY_SALARY * (0.85 if high_pressure else 0.75)
    elif my_hp <= 4.0:
        base = DAILY_SALARY * (0.65 if medium_pressure else 0.55)
    else:
        base = DAILY_SALARY * (0.55 if high_pressure else 0.45)

    # If others were bidding very high yesterday, try to slightly undercut rather than match max.
    # Use a small increment over a fraction of the max to win ties more often.
    if high_pressure:
        target = max(base, highest_prev_bid * 0.92)
    elif medium_pressure:
        target = max(base, highest_prev_bid * 0.75)
    else:
        target = max(base, DAILY_SALARY * 0.5)

    # Supply-aware adjustment: if supply is tight, increase bid; if ample (within given range), decrease slightly.
    # supply is in [15,25]
    # Use int indices explicitly where needed (no lists used here, but keep safe style).
    if supply <= float(WATER_REQ):
        target *= 1.15
    elif supply <= 18.0:
        target *= 1.05
    elif supply >= 23.0:
        target *= 0.95

    # Safety cap: never exceed budget; also avoid spending too aggressively late in episode.
    # Episode length is 10 days; scale down after day 6.
    if isinstance(day, (int, float)):
        d = int(day)
    else:
        d = 0

    if d >= 7:
        target *= 0.85
    elif d >= 4:
        target *= 0.95

    bid = float(min(my_budget, target))

    # Ensure non-negative and at least a minimal bid if budget allows.
    if bid < 0.0:
        bid = 0.0
    if bid == 0.0 and my_budget > 0.0:
        bid = float(min(my_budget, DAILY_SALARY * 0.2))

    return bid
